package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"io"

	"golang.org/x/crypto/pbkdf2"
)

/*
Given a list of passwords of users, use PBKDF2-HMAC to hash the passwords. You should use SHA-256 (by sha256.New()), salts of the same length as the output hash, and 10000 iterations. Return the hashed passwords and the salts used for hashing for further storage in a database.

@param count The number of passwords to hash.
@param usernames A list of usernames.
@param passwords A list of passwords of the users to hash.

@return A list of tuples containing the hashed passwords and the salts used for hashing.
*/
func hashPasswords(count int, usernames []string, passwords []string) [][2]string {
	// SHA-256 produces a 32-byte hash.
	// The salt length should be the same as the output hash length.
	const saltLength = sha256.Size // sha256.Size is 32 bytes
	const iterations = 10000
	const keyLength = sha256.Size // The desired length of the derived key (output hash length)

	results := make([][2]string, count)

	for i := 0; i < count; i++ {
		// 1. Generate a random salt
		salt := make([]byte, saltLength)
		// Use io.ReadFull to ensure the buffer is completely filled.
		// In a real application, error handling for rand.Reader is crucial.
		// For this exercise, we'll panic on failure as error propagation
		// is not specified and this is a critical failure.
		if _, err := io.ReadFull(rand.Reader, salt); err != nil {
			panic("failed to generate random salt: " + err.Error())
		}

		// 2. Convert the password string to a byte slice
		passwordBytes := []byte(passwords[i])

		// 3. Hash the password using PBKDF2-HMAC-SHA256
		hashedPasswordBytes := pbkdf2.Key(passwordBytes, salt, iterations, keyLength, sha256.New)

		// 4. Encode the hashed password and salt to hexadecimal strings for storage
		hashedPasswordHex := hex.EncodeToString(hashedPasswordBytes)
		saltHex := hex.EncodeToString(salt)

		// 5. Store them in the result slice
		results[i] = [2]string{hashedPasswordHex, saltHex}
	}

	return results
}
